from wd_common import *
i=5
Z=lambda q,a:[('z',q),('b',a)]
import math
def ring(cx,cy,rx,ry,n,cols=('#c0392b','#1d4f8a','#2a9d6f','#e0a800'),sc=.6):
    o=f'<ellipse cx="{cx}" cy="{cy}" rx="{rx}" ry="{ry}" fill="none" stroke="#e0a800" stroke-width="3" stroke-dasharray="8 6"/>'
    for k in range(n):
        a=2*math.pi*k/n; o+=g(cx+rx*math.cos(a),cy+ry*math.sin(a)+20,sc,person(cols[k%4]))
    return o
def arrow(cx,cy,r): return f'<path d="M{cx+r} {cy} l-8 -10 M{cx+r} {cy} l8 -10" stroke="#e0a800" stroke-width="3"/>'
def shrine(): return '<rect x="-40" y="-60" width="80" height="60" fill="#e9d6c0"/><path d="M-50 -60 L0 -110 L50 -60z" fill="#7a3b1f"/><rect x="-10" y="-30" width="20" height="30" fill="#3a1a0a"/>'
def peepal(): return '<path d="M0 0 v-70" stroke="#6a4a2a" stroke-width="10"/><circle cy="-90" r="50" fill="#3a8a4a"/>'+''.join(f'<path d="M{a} -40 v40" stroke="#c0392b" stroke-width="2"/>' for a in (-14,0,14))
def hill(): return '<path d="M-120 0 L-30 -110 L0 -90 L40 -130 L120 0z" fill="#7a6a5a"/>'
fw=foreword(i,['In a temple, after seeing the god, people walk slowly round the shrine, always keeping it on their right. At home, at the end of pūjā, some turn round in place. Pilgrims walk round whole hills and rivers. This walking round is <b>pradakṣiṇā</b>, and it is one of the oldest acts of reverence in India.',
 'This part explains the word and the direction, the temple path, how many rounds and how, the special rule at Śiva temples, walking round trees, fire and hills, the story of Gaṇeśa circling his parents, rolling round temples as a vow, and what it means.',
 'Previous: '+L('/why-do-we/bell/','the bell')+'. Next: '+L('/why-do-we/namaskara/','namaskāra')+'. Temple plans: '+L('/temples-of-india/how-to-read-a-hindu-temple/','How to read a Hindu temple')+'.'],Z('Why always the same direction?','So that God is always on your right, the side of honour.'))
gl=glance([('Word','Pradakṣiṇā: “towards the right”'),('Direction','Clockwise, the deity always on the right'),('Path','Pradakṣiṇā-patha round the sanctum or temple'),('Rounds','Commonly 1, 3, 5, 7 or 108; customs vary'),('Pace','Slow, with prayer or the god’s name'),('Śiva','Some keep a half-round, not crossing the abhiṣeka outlet'),('Trees','Aśvattha (peepal), tulasī'),('Fire','Bride and groom circle the sacred fire'),('Hills','Aruṇācala, Govardhana: giri-pradakṣiṇā'),('Meaning','God at the centre of one’s life')],
 S('Devotees walking clockwise round a shrine with arrows',ring(280,160,200,50,8)+g(280,170,1.2,shrine())+arrow(480,160,0),'#fff3cf',230),Z('Is anticlockwise wrong?','Anticlockwise circling is kept for funeral and ancestral rites in many traditions. In a temple, go right.'),'God <b>at the centre</b>.')
word=reading('word','THE WORD','Towards the right',S('A figure walking with the shrine on the right-hand side',g(280,215,1.4,shrine())+g(180,215,1.4,person('#1d4f8a'))+'<path d="M200 230 C250 250 330 250 380 230" stroke="#e0a800" stroke-width="3" fill="none"/>'+T(380,120,'right side',11),'#fff3cf',215),
 ['<b>Pradakṣiṇā.</b> From dakṣiṇa, “right” (also “south”) and pra, “towards”: moving so the object of reverence is on the right.','<b>Clockwise.</b> Walking round with the deity on your right means moving clockwise.','<b>Old.</b> Circling to the right as honour is found in Vedic ritual and in Buddhist and Jain worship.','<b>Parikramā.</b> In the north the word parikramā is common, especially for long circuits.','<b>The right side.</b> The right is the side of honour and auspiciousness in Indian custom.'],Z('Dakṣiṇa also means south?','Face east to pray, and south is on your right. The two meanings meet.'),'Keep God <b>on your right</b>.')
path=reading('path','THE TEMPLE PATH','Corridors made for walking round',S('A temple plan with a sanctum surrounded by a walking corridor and outer path',g(280,130,1,'<rect x="-200" y="-100" width="400" height="200" fill="#e9d6c0" stroke="#7a3b1f" stroke-width="4"/><rect x="-120" y="-60" width="240" height="120" fill="#f7ead2" stroke="#7a3b1f" stroke-width="3"/><rect x="-40" y="-30" width="80" height="60" fill="#3a1a0a"/>')+'<ellipse cx="280" cy="130" rx="160" ry="80" fill="none" stroke="#e0a800" stroke-width="3" stroke-dasharray="8 6"/><ellipse cx="280" cy="130" rx="80" ry="45" fill="none" stroke="#e0a800" stroke-width="3" stroke-dasharray="8 6"/>','#fff3cf',230),
 ['<b>Built for it.</b> Many temples have a covered corridor (pradakṣiṇā-patha) round the sanctum.','<b>Rings.</b> Big temples have several rings (prākāras); the devotee may circle one or all.','<b>Shrines on the way.</b> Smaller shrines along the path are greeted in turn.','<b>Outer path.</b> Festival processions follow the outer streets round the temple.','<b>Read more.</b> '+L('/temples-of-india/how-to-read-a-hindu-temple/','How to read a Hindu temple')+'.'],Z('Do I have to go round all the rings?','One round of the inner path is enough for a daily visit.'),'A temple <b>shaped for walking</b>.')
how=reading('how','HOW IT IS DONE','Slow, steady, with prayer',S('A devotee walking with palms joined, lips moving',g(280,215,2,person('#c0392b'))+'<path d="M266 130 l14 -10 l14 10" stroke="#e8c3a0" stroke-width="6" fill="none"/>'+T(380,110,'nāma…',12),'#fff3cf',215),
 ['<b>Slowly.</b> Tradition compares the ideal pace to a pregnant woman’s careful walk. (Common teaching.)','<b>Joined palms.</b> Hands in namaskāra, or holding flowers.','<b>Name.</b> Chanting the god’s name or a short prayer while walking.','<b>Bow at the front.</b> At each pass of the sanctum door, a bow or namaskāra.','<b>Rounds.</b> Odd numbers are common: 1, 3, 5, 7, 21, 108. (Customs vary.)'],Z('Can I count on my fingers?','Many use flowers or stones. Some temples have counters at the door.'),'Walk <b>as if carrying something precious</b>.')
shiva=reading('shiva','AT ŚIVA TEMPLES','The half round',S('A Śiva shrine with the water outlet; a path that turns back before crossing it',g(280,170,1.4,shrine())+'<path d="M320 160 h60" stroke="#4aa3df" stroke-width="8"/>'+'<path d="M380 180 C380 240 180 240 180 180 C180 120 300 110 360 130" stroke="#e0a800" stroke-width="3" fill="none" stroke-dasharray="8 6"/>'+arrow(360,130,0),'#e3eaf3',230),
 ['<b>The outlet.</b> The water poured on the Śiva liṅga flows out through a channel (praṇāla), often on the north side.','<b>Not crossed.</b> In many Śaiva traditions the devotee does not cross this outlet: he walks up to it, turns back, and completes the round the other way. This is often called <b>somasūtra</b> or candra pradakṣiṇā.','<b>Reason given.</b> The abhiṣeka water is sacred and should not be stepped over. (Traditional reason.)','<b>Not everywhere.</b> Many Śiva temples, especially in the south, are circled fully. (Practices differ.)','<b>Ask.</b> Follow the local custom of the temple.'],Z('So in a Śiva temple I go half way and turn?','In those that keep the rule, yes. Watch the others.'),'Respect <b>the sacred water</b>.')
tree=reading('trees','ROUND TREES','Aśvattha and tulasī',S('Women walking round a peepal tree with threads tied on it',g(280,215,1.6,peepal())+ring(280,200,150,30,6,sc=.55),'#d8e8c8',215),
 ['<b>Aśvattha.</b> The peepal (aśvattha) tree is circled by devotees, often in the morning; it is linked with Viṣṇu and with the trinity. (Tradition.)','<b>Threads.</b> Women tie threads round it for family welfare and children.','<b>Nāga stones.</b> In Karnataka, nāga stones under the peepal-and-neem pair are circled together.','<b>Tulasī.</b> At home the tulasī plant is circled after pūjā (see '+L('/why-do-we/tulasi/','Part 8')+').','<b>Saturdays and amāvāsyā.</b> Some days are especially kept for tree pradakṣiṇā. (Customs vary.)'],Z('Why the peepal?','Old, shady, sacred to many gods. The Gītā has Kṛṣṇa say: among trees, I am the aśvattha.'),'Circling <b>the sacred tree</b>.')
fire=reading('fire','ROUND THE FIRE','Wedding rounds',S('A bride and groom walking round a sacred fire',g(280,200,1.6,'<path d="M-30 0 h60 l-10 -20 h-40z" fill="#7a3b1f"/>'+g(0,-20,1.2,flame()))+ring(280,190,120,30,2,('#c0392b','#f4f1ea'),.8),'#fff3cf',215),
 ['<b>Agni.</b> In many Hindu weddings the couple walk round the sacred fire, keeping it on the right.','<b>Witness.</b> Agni is the witness of the marriage.','<b>Rounds.</b> The number of rounds and how they relate to the seven steps (saptapadī) differ by community.','<b>Homa.</b> Fire rituals also end with circling the fire in some traditions.','<b>Same act.</b> Honour shown to the fire as to a deity.'],Z('Seven rounds?','In some traditions. In others, the seven steps are walked beside the fire. Both are honoured.'),'The fire <b>as witness</b>.')
ganesha=story('ganesha','THE GREAT RACE','Gaṇeśa circles his parents',strip('Three panels: Kārttikeya flies off on a peacock; Gaṇeśa walks round Śiva and Pārvatī; Gaṇeśa receives the prize',
 [('<rect width="144" height="190" fill="#d8e8f0"/>'+g(72,120,.6,'<ellipse rx="30" ry="12" fill="#1d4f8a"/><path d="M20 0 q30 -20 30 -40" stroke="#2a9d6f" stroke-width="6" fill="none"/>')+g(72,100,.5,god('#c0392b')),'#d8e8f0'),
  ('<rect width="144" height="190" fill="#fff3cf"/>'+g(60,170,.6,god('#7a9aaa'))+g(90,170,.6,devi(items=()))+'<ellipse cx="75" cy="150" rx="60" ry="24" fill="none" stroke="#e0a800" stroke-width="2" stroke-dasharray="5 4"/>'+g(130,180,.5,god('#e08a2a')),'#fff3cf'),
  ('<rect width="144" height="190" fill="#fff3cf"/>'+g(72,180,.7,god('#e08a2a'))+g(72,90,.6,'<circle r="12" fill="#f4f1ea"/><circle cx="16" r="10" fill="#f4f1ea"/>'),'#fff3cf')],['round the world','round the parents','the prize']),'A Purāṇic story, told in many versions.',
 ['Śiva and Pārvatī promise a prize (a fruit, in many tellings) to whichever son first goes round the world.','Kārttikeya flies off on his peacock. Gaṇeśa simply walks round his parents: “You are my world.”','The prize goes to Gaṇeśa. The lesson: pradakṣiṇā of what is truly central is complete.'])
hills=reading('hills','ROUND HILLS AND RIVERS','The great circuits',S('A line of pilgrims walking round a sacred hill at night under a full moon',g(280,200,1.6,hill())+g(460,50,1,moon())+'<ellipse cx="280" cy="200" rx="220" ry="26" fill="none" stroke="#e0a800" stroke-width="3" stroke-dasharray="8 6"/>'+''.join(g(80+k*80,226,.5,person('#f4f1ea')) for k in range(6)),'#20243a',230),
 ['<b>Giri-pradakṣiṇā.</b> Pilgrims walk round sacred hills barefoot: <b>Aruṇācala</b> at Tiruvaṇṇāmalai, especially on full-moon nights, and <b>Govardhana</b> near Mathurā.','<b>Rivers.</b> The <b>Narmadā parikramā</b> walks both banks of the river, source to sea and back, over months.','<b>Cities.</b> Kāśī’s pañcakrośī circuit walks round the sacred city.','<b>Places as gods.</b> The hill or river itself is the deity, so circling it is worship.','<b>Read.</b> '+L('/temples-of-india/pancha-bhuta-sthalas/','Pañca Bhūta Sthalas')+' (Aruṇācala as fire).'],Z('Walking round a whole river?','Some take years. The river is the temple.'),'When the hill <b>is the god</b>.')
roll=reading('angapradakshina','ROLLING ROUND','Aṅga-pradakṣiṇā',S('A devotee rolling on the ground round a temple',g(280,170,1.2,shrine())+'<ellipse cx="280" cy="200" rx="200" ry="30" fill="none" stroke="#e0a800" stroke-width="3" stroke-dasharray="8 6"/>'+g(140,210,.9,'<rect x="-30" y="-10" width="60" height="16" rx="8" fill="#f4f1ea"/><circle cx="36" cy="-2" r="8" fill="#e8c3a0"/>'),'#fff3cf',215),
 ['<b>A vow.</b> In aṅga-pradakṣiṇā the devotee lies down and rolls round the temple, as a vow (harake) or thanksgiving.','<b>Where.</b> It is seen at temples such as Kukke Subrahmaṇya and Tirumala, among others.','<b>Body offered.</b> The whole body (aṅga) is offered in humility. (Interpretation.)','<b>Debate.</b> Some practices of this kind have been debated and regulated; this site describes, not prescribes.','<b>Prostration rounds.</b> Others circle by prostrating fully at each step.'],Z('Isn’t that hard?','Very. That is the point of a vow.'),'The whole body <b>bowed</b>.')
mean=reading('meaning','WHAT IT MEANS','God at the centre',S('Planets circling the sun; a person circling a shrine',g(160,130,1,'<circle r="22" fill="#f0c030"/>'+''.join(f'<ellipse rx="{r}" ry="{r*.4}" fill="none" stroke="#9aa"/>' for r in (40,60,80)))+g(420,200,1,shrine())+'<ellipse cx="420" cy="190" rx="90" ry="24" fill="none" stroke="#e0a800" stroke-width="3" stroke-dasharray="8 6"/>','#20243a',215),
 ['<b>Centre.</b> Walking round says: God is at the centre of my life; I move round him. (Common teaching.)','<b>Like the planets.</b> The planets circle the sun; teachers use the image. (Interpretation.)','<b>Ātma-pradakṣiṇā.</b> At home, turning round in place at the end of pūjā honours the god within. (Practice and interpretation.)','<b>Every side.</b> Circling lets the devotee honour the deity from every direction.','<b>Walking prayer.</b> It turns the body’s movement into worship.'],Z('Turning round in place counts?','At home, where there is no path, yes. The god inside you is circled.'),'Move round <b>what matters most</b>.')
endp=end(i,['<b>Word.</b> Pradakṣiṇā: keeping the sacred on the right; clockwise.','<b>Temple.</b> A path round the sanctum; slow, with prayer; odd rounds.','<b>Śiva.</b> In some traditions, a half round, not crossing the water outlet.','<b>Beyond.</b> Trees, the wedding fire, hills, rivers, cities.','<b>Meaning.</b> God at the centre; Gaṇeśa’s round of his parents.'],'Part 7 is namaskāra.','God at the centre')
src=sources([('Practice:','Wikipedia, “Parikrama” (meaning, temple paths, giri-pradakṣiṇā, Narmadā parikramā, aṅga-pradakṣiṇā); common Śaiva temple custom (somasūtra pradakṣiṇā); the Gaṇeśa and Kārttikeya story as told in Purāṇic retellings; Bhagavad Gītā 10.26 (aśvattha among trees, sense).')],'the number of rounds, the somasūtra rule, tree-circling days and the pace teaching vary by tradition; readings marked as interpretation are teachers’.','No verse text is reproduced in this part.')
finish(i,'PART 6 OF 10 · CLOCKWISE · TEMPLE · HILL',covart('Devotees walking clockwise round a shrine',ring(220,150,170,40,8,sc=.5)+g(220,160,1,shrine())),'God at the centre',
 'Why we do <b>pradakṣiṇā</b>: the word and direction, the temple path, how to walk it, the half-round at Śiva temples, trees and fire, <b>Gaṇeśa’s round</b>, hills and rivers, and rolling vows.',
 'Why do we do pradakṣiṇā? Explained and illustrated: meaning, clockwise circling, temple paths, rounds and pace, Śiva somasūtra, aśvattha and tulasī, wedding fire, Gaṇeśa circling his parents, giri-pradakṣiṇā, aṅga-pradakṣiṇā.',
 [fw,gl,word,path,how,shiva,tree,fire,ganesha,hills,roll,mean,endp,src])
